update core.tactics_shared_items item
set details = $json${"part":"warmup","minutes":8,"players":8,"area":"25 × 20 m","organisation":"Fyra banor med fem koner var, en spelare i varje ände. Spelaren med boll dribblar genom konerna, passar till kompisen i andra änden och tar dennes plats. Korta stafetter med teknikinslag som höjer pulsen och skärper tekniken. Byt teknik varje varv: insida, utsida, bara vänster, bara höger, fint vid sista konen.","coaching_points":"Små touch nära foten genom konerna.\nBlicken upp mellan konerna, inte bara på bollen.\nBromsa bollen med sulan i varje vändning.\nÖka tempot varvet ut: sista varvet som en tävling mellan banorna.","phase":null,"age_classes":["7-9","10-12","13-15"],"game_forms":["5v5","7v7","9v9"]}$json$::jsonb,
