set details = $json${"part":"main","minutes":20,"players":10,"area":"25 × 25 m","organisation":"Spel 4 mot 4 i en yta på 25 × 25 meter med två lila jokrar på kanterna som spelar med laget som har bollen. Laget med boll ska hålla den, tio passningar i rad ger ett poäng. Laget utan boll tränar att läsa tydliga signaler för press och reagera samtidigt: när signalen kommer kliver alla fyra på en gång. 4 × 4 minuter.","coaching_points":"Signaler att pressa: bakåtpassning, dålig mottagning, spelare med ryggen mot spelriktningen och passning mot kanten.\nRopa signalen högt, till exempel \"Nu!\", så att alla kliver samtidigt.\nDen närmaste pressar bollen, de andra tar närmaste passningsalternativ.\nIngen signal: håll ihop och vänta, jaga inte ensam.","phase":"regaining","age_classes":["13-15","16+"],"game_forms":["9v9","11v11"]}$json$::jsonb,
