set details = $json${"part":"finish","minutes":15,"players":14,"area":"50 × 35 m","organisation":"Matchspel 6 mot 6 med målvakter på en plan på 50 × 35 meter. Planen delas på mitten med koner. Varje bollvinst högt upp, på motståndarnas planhalva, ska leda till ett snabbt avslut inom tre passningar. Mål efter bollvinst på motståndarnas halva räknas dubbelt. Målvakten startar spelet vid varje ny boll.","coaching_points":"Pressa direkt när motståndarnas målvakt spelar ut till en back.\nStyr spelet mot kanten, där sidlinjen hjälper till.\nEfter bollvinst: framåt först. Max tre passningar till avslut, räkna högt.\nDe som inte vinner bollen löper mot mål direkt, inte bort från det.","phase":"regaining","age_classes":["13-15","16+"],"game_forms":["9v9","11v11"]}$json$::jsonb,
