update core.tactics_shared_items item
set details = $json${"part":"main","minutes":15,"players":7,"area":"Halvplan","organisation":"Backlinje och målvakt tränar att skapa spelbara vinklar mot en pressande motståndare. Målvakten och fyra backar mot två anfallare på egen planhalva. Blå ska spela sig ut och dribbla igenom ett av två konmål vid mittlinjen. Vinner röd bollen får de avsluta på mål. Ny boll från målvakten varje gång.","coaching_points":"Mittbackarna går isär och brett, ut mot straffområdets hörn, när målvakten har bollen.\nYtterbackarna högt och brett, nära sidlinjen.\nÖppna kroppen vid mottagningen så du ser hela planen.\nSpela till den som är fri: runt pressen eller igenom den.\nMålvakten är alltid ett säkert alternativ bakåt.","phase":"build_up","age_classes":["10-12","13-15","16+"],"game_forms":["7v7","9v9","11v11"]}$json$::jsonb,
