set details = $json${"part":"main","minutes":20,"players":18,"area":"70 × 50 m","organisation":"Positionsspel 8 mot 8 med målvakter på en plan på ungefär 70 × 50 meter, delad i tre lika stora zoner. Laget måste ha minst en passning i varje tredjedel innan det får göra mål. Övningen belönar laget för att spela sig igenom planens alla tredjedelar med kontroll. Mål efter att ha spelat genom alla tre zoner med en spelare mellan motståndarens linjer räknas dubbelt.","coaching_points":"Sök spelare mellan motståndarens linjer: dit vill vi.\nBredd: ytterspelarna nära sidlinjen drar isär motståndarna.\nHellre en passning bakåt än en chansning framåt.\nRörelse utan boll: skapa vinklar så att bollhållaren har två alternativ.","phase":"build_up","age_classes":["13-15","16+"],"game_forms":["9v9","11v11"]}$json$::jsonb,
