set details = $json${"part":"finish","minutes":15,"players":14,"area":"55 × 36 m","organisation":"Spel 7 mot 7 med målvakter på en sjumannaplan. Laget måste slå minst fyra passningar i uppbyggnaden innan avslut är tillåtet. Målvakten startar spelet efter varje mål och varje boll över kortlinjen. Tränaren räknar passningarna högt.","coaching_points":"Backarna går brett direkt när vi vinner bollen eller målvakten har den.\nMålvakten är med i spelet: ett säkert alternativ bakåt.\nSpela framåt när det är öppet, annars runt.\nTänk på kroppsställningen vid mottagning: se framåt.","phase":"build_up","age_classes":["10-12","13-15","16+"],"game_forms":["7v7","9v9"]}$json$::jsonb,
