update core.tactics_shared_items item
set details = $json${"part":"main","minutes":20,"players":12,"area":"40 × 30 m","organisation":"Åtta röda runt och i en yta på 40 × 30 meter mot fyra blå. Röd ska spela in bollen i den gula mittzonen till en medspelare. Överläge för det anfallande laget tvingar försvararna att hålla avstånden och täcka de centrala ytorna. Blå får ett poäng för varje bollvinst och för varje minut utan att röd har spelat in i mittzonen. Byt fyra var tredje minut.","coaching_points":"De fyra håller ihop: högst tio meter mellan varandra.\nStäng mitten först, låt röd spela utanpå.\nFlytta mot bollen tillsammans, som om ni var bundna med ett rep.\nDen närmaste kliver, de andra täcker bakom och stänger in-passningen.","phase":"defending","age_classes":["13-15","16+"],"game_forms":["9v9","11v11"]}$json$::jsonb,
